package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.server.level.*;import net.neoforged.neoforge.items.IItemHandler;
public class DwfBlockEntity extends BlockEntity{
 private UUID storageId,owner;private DwfMachine machine;private IItemHandler port;private boolean removing;public long visualTick,progress;public int required=1,inputViewers,outputViewers;public String visualStatus="OFF";public net.minecraft.world.item.ItemStack product=net.minecraft.world.item.ItemStack.EMPTY;
 public DwfBlockEntity(BlockPos p,BlockState s){super(AddonBlockEntities.DWF01.get(),p,s);}
 public UUID id(){return storageId;}public UUID owner(){return owner;}
 public static DwfBlockEntity create(BlockPos p,BlockState s){return DwfGeometry.chest(s.getValue(DwfBlock.PART))>=0?new DwfPortBlockEntity(p,s):new DwfBlockEntity(p,s);}public Direction facing(){return getBlockState().getValue(DwfBlock.FACING);}public boolean controller(){return getBlockState().getValue(DwfBlock.PART)==0;}
 public DwfMachine machine(){return machine;}public void initialize(UUID id,UUID owner){this.storageId=id;this.owner=owner;setChanged();attach();}
 @Override public void onLoad(){super.onLoad();if(level!=null&&level.isClientSide)DwfAudio.watch(this);if(level instanceof ServerLevel server&&controller())server.getServer().execute(()->{if(!isRemoved()&&!DwfBlock.MUTATING.get())attach();});}
 private void attach(){if(!(level instanceof ServerLevel server)||!controller()||machine!=null||isRemoved())return;if(storageId==null)storageId=UUID.randomUUID();if(!DwfClaims.get(server).claim(storageId,level.dimension().location().toString(),worldPosition.asLong())){SbwDroneRangeConfig.LOGGER.error("Duplicate DWF storage identity {} at {} is locked",storageId,worldPosition);return;}machine=new DwfMachine(this,DwfServer.context(server.getServer()));setChanged();}
 public boolean allowed(Player player){return !isRemoved()&&level.mayInteract(player,worldPosition)&&DwfGeometry.bounds(worldPosition,facing()).inflate(6).contains(player.position());}
 public void open(ServerPlayer player,int chest){if(machine==null||!machine.ready()){player.displayClientMessage(net.minecraft.network.chat.Component.literal(machine==null?"Fabricator unavailable":machine.error()),true);return;}DwfMenu.open(player,this,chest);}
 public boolean hasContents(){return machine==null||!machine.ready()||machine.input.counts.total()>0||machine.output.counts.total()>0;}
 public void visualChanged(){if(level==null||level.isClientSide)return;setChanged();if(level instanceof ServerLevel server){var packet=getUpdatePacket();for(var player:server.getChunkSource().chunkMap.getPlayers(new net.minecraft.world.level.ChunkPos(worldPosition),false))player.connection.send(packet);}}
 public void dismantle(boolean drop){if(removing||!(level instanceof ServerLevel server))return;removing=true;var packed=new net.minecraft.world.item.ItemStack(AddonItems.DWF01.get());if(storageId==null)storageId=UUID.randomUUID();var packedId=storageId;net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,packed,tag->{tag.putUUID("DwfStorage",packedId);tag.putUUID("DwfWorld",DwfClaims.get(server).worldId);});if(machine!=null){machine.close();machine=null;}DwfClaims.get(server).release(storageId);DwfBlock.MUTATING.set(true);try{for(int i=1;i<DwfGeometry.CELLS.length;i++){var at=DwfGeometry.cell(worldPosition,facing(),i);var state=level.getBlockState(at);if(state.getBlock()instanceof DwfBlock&&DwfGeometry.root(at,state.getValue(DwfBlock.FACING),state.getValue(DwfBlock.PART)).equals(worldPosition))level.removeBlock(at,false);}level.removeBlock(worldPosition,false);}finally{DwfBlock.MUTATING.set(false);}if(drop)net.minecraft.world.level.block.Block.popResource(level,worldPosition,packed);}
 @Override public void setRemoved(){if(level instanceof ServerLevel server&&level.restoringBlockSnapshots&&controller()&&storageId!=null)DwfClaims.get(server).release(storageId);if(machine!=null){machine.close();machine=null;}port=null;super.setRemoved();}
 public IItemHandler handler(){int chest=DwfGeometry.chest(getBlockState().getValue(DwfBlock.PART));if(chest<0)return null;if(port==null)port=new DwfPortHandler(this,chest);return port;}
 public DwfBlockEntity root(){return controller()?this:level==null?null:DwfBlock.main(level,worldPosition,getBlockState());}
 @Override protected void saveAdditional(CompoundTag tag,net.minecraft.core.HolderLookup.Provider registry){super.saveAdditional(tag,registry);if(storageId!=null)tag.putUUID("Storage",storageId);if(owner!=null)tag.putUUID("Owner",owner);}
 @Override public void loadAdditional(CompoundTag tag,net.minecraft.core.HolderLookup.Provider registry){super.loadAdditional(tag,registry);storageId=tag.hasUUID("Storage")?tag.getUUID("Storage"):null;owner=tag.hasUUID("Owner")?tag.getUUID("Owner"):null;visualTick=tag.getLong("Tick");progress=tag.getLong("Progress");required=Math.max(1,tag.getInt("Required"));visualStatus=tag.getString("Status");inputViewers=tag.getInt("InputViewers");outputViewers=tag.getInt("OutputViewers");product=tag.contains("Product")?net.minecraft.world.item.ItemStack.parseOptional(registry,tag.getCompound("Product")):net.minecraft.world.item.ItemStack.EMPTY;if(level!=null&&level.isClientSide)DwfAudio.watch(this);}
 @Override public CompoundTag getUpdateTag(net.minecraft.core.HolderLookup.Provider registry){var tag=new CompoundTag();if(machine!=null){var r=machine.production.recipe();tag.putLong("Tick",level.getGameTime());tag.putLong("Progress",machine.production.progress());tag.putInt("Required",r==null?1:r.ticks());tag.putString("Status",machine.presentationState());if(r!=null)tag.put("Product",r.output().stack(1).save(registry));}tag.putInt("InputViewers",inputViewers);tag.putInt("OutputViewers",outputViewers);return tag;}
 @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
 public net.minecraft.world.phys.AABB getRenderBoundingBox(){return DwfGeometry.bounds(worldPosition,facing());}
}
